    variable result : register_t := (others => '-');
  begin
    result(can_fd_fi_CORE_VERSION_magic_valid) := std_ulogic_vector(data.magic_valid);
    result(can_fd_fi_CORE_VERSION_patch) := std_ulogic_vector(data.patch);
    result(can_fd_fi_CORE_VERSION_minor) := std_ulogic_vector(data.minor);
    result(can_fd_fi_CORE_VERSION_major) := std_ulogic_vector(data.major);

    return result;
  end function;

  function to_can_fd_fi_CORE_VERSION(data : register_t) return can_fd_fi_CORE_VERSION_t is
    variable result : can_fd_fi_CORE_VERSION_t := can_fd_fi_CORE_VERSION_init;
  begin
    result.magic_valid := can_fd_fi_CORE_VERSION_magic_valid_t(data(can_fd_fi_CORE_VERSION_magic_valid));
    result.patch := can_fd_fi_CORE_VERSION_patch_t(data(can_fd_fi_CORE_VERSION_patch));
    result.minor := can_fd_fi_CORE_VERSION_minor_t(data(can_fd_fi_CORE_VERSION_minor));
    result.major := can_fd_fi_CORE_VERSION_major_t(data(can_fd_fi_CORE_VERSION_major));

    return result;
  end function;

  function to_slv(data : can_fd_fi_STATUS_FLAGS_t) return register_t is
    variable result : register_t := (others => '-');
  begin
    result(can_fd_fi_STATUS_FLAGS_tu_ready_config) := data.tu_ready_config;
    result(can_fd_fi_STATUS_FLAGS_inj_err_miss) := data.inj_err_miss;
    result(can_fd_fi_STATUS_FLAGS_inj_err_dom) := data.inj_err_dom;
    result(can_fd_fi_STATUS_FLAGS_inj_err_dlc) := data.inj_err_dlc;
    result(can_fd_fi_STATUS_FLAGS_inj_err_fsm) := data.inj_err_fsm;

    return result;
